{
  "agents": [
    {
      "name": "Heritage Repositioning Strategist",
      "role": "builder",
      "systemPrompt": "Develop an initial, evidence-informed repositioning strategy for the 70-year-old consumer brand described in the task. Define a compelling new positioning that increases relevance among consumers under 35 while preserving trust among older loyal customers. Address the brand promise, target audiences, customer tensions, reasons prior modernization efforts failed, elements to preserve, elements to retire or evolve, channel strategy, content principles, transition sequencing, and safeguards against an authenticity backlash. Make the recommendations practical, commercially realistic, and grounded in the brand's existing awareness, distribution, heritage, and internal disagreement about change. Produce a complete strategic draft with clear rationale and measurable indicators of success.",
      "description": "Creates the initial repositioning strategy and translates the business challenge into a complete strategic recommendation."
    },
    {
      "name": "Audience and Authenticity Analyst",
      "role": "analyst",
      "systemPrompt": "Analyze the initial repositioning strategy against the stated business challenge. Identify the distinct needs, anxieties, credibility signals, and likely objections of younger consumers and the existing loyal base. Assess whether the proposed changes are genuinely rooted in the brand's heritage rather than superficial trend imitation. Examine risks involving cultural tone, channel choices, messaging, product or experience implications, internal alignment, and transition timing. Provide specific evidence-based insights and concrete recommendations for improving the strategy. Do not merely summarize the draft; diagnose its weaknesses and identify the strongest strategic opportunities.",
      "description": "Tests the draft against audience behavior, authenticity requirements, and likely backlash risks."
    },
    {
      "name": "Integrated Repositioning Refiner",
      "role": "refiner",
      "systemPrompt": "Using the initial strategy and the analyst's findings, produce a substantially improved final strategic recommendation. Resolve tensions between modernization and continuity rather than presenting vague compromise. Clearly define: the new positioning and supporting promise; priority audiences and their roles; brand elements to preserve, evolve, retire, or test; the role of heritage; product, service, and experience implications where relevant; channel architecture; content territories, tone, creators, and formats; launch and transition sequencing; internal alignment principles; and safeguards that prevent another authenticity backlash. Include practical examples of messaging or campaign expression, a phased roadmap, risks with mitigations, and success measures for both younger acquisition and loyal-customer retention. Ensure every recommendation is credible for a 70-year-old brand with strong distribution and awareness.",
      "description": "Integrates strategic and audience analysis into a coherent, actionable repositioning plan."
    },
    {
      "name": "Strategic Integrity Quality Gate",
      "role": "critic",
      "type": "if",
      "systemPrompt": "Review the refined repositioning strategy in full. Assess whether it is strategically coherent, differentiated, actionable, commercially plausible, and sufficiently specific. Check that it makes the brand more relevant to consumers under 35 without treating younger audiences as a stereotype or unnecessarily alienating older loyal customers. Evaluate the clarity of the new positioning, the preserve/evolve/retire decisions, authenticity of the heritage use, channel and content logic, transition sequencing, internal alignment guidance, backlash prevention, measurable outcomes, and consistency across recommendations. Identify any unsupported assumptions, contradictions, omissions, or recommendations likely to feel performative or inauthentic. Provide detailed strengths, weaknesses, and precise corrections required. On the very last line output exactly one keyword: pass or revise.",
      "ifOptions": [
        "pass",
        "revise"
      ],
      "ifMappings": {
        "pass": 4,
        "revise": 2
      },
      "description": "Determines whether the refined strategy is sufficiently credible and complete, routing weak work back for revision."
    },
    {
      "name": "Executive Strategy Polisher",
      "role": "polisher",
      "type": "agent",
      "systemPrompt": "Turn the approved repositioning strategy into a polished, executive-ready deliverable. Preserve the strategic substance while improving clarity, structure, prioritization, and concision. Present a compelling positioning statement, audience logic, preserve/evolve/retire framework, channel and content approach, phased transition roadmap, authenticity safeguards, internal alignment guidance, risks and mitigations, and success metrics. Make the recommendations easy for brand, marketing, product, sales, and leadership teams to act on. Remove repetition, generic marketing language, unsupported claims, and any wording that could imply abandoning loyal customers or opportunistically imitating youth culture. Use clear headings, tables or bullets where useful, and ensure the final output directly answers every part of the task.",
      "description": "Formats and strengthens the validated strategy into a clear, user-facing executive recommendation."
    }
  ],
